import React from "react";
import { Routes, Route } from "react-router-dom";
import Home from "./pages/Home";
import BottomNav from "./components/BottomNav";

function MobileApp() {
  // REMOVED: React.createElement(Router, null, ...) 
  // We only return the DIV and the ROUTES now.

  return React.createElement(
    "div",
    { className: "mobile-container" },

    // 1. The Main Content (Routes)
    React.createElement(
      Routes,
      null,
      // Note: use path="/" or "" because this is already inside the "/mobile" parent route
      React.createElement(Route, {
        index: true,
        element: React.createElement(Home, null)
      }),
      // This catches anything inside /mobile/ that isn't defined
      React.createElement(Route, {
        path: "*",
        element: React.createElement(Home, null)
      })
    ),

    // 2. The Navigation Bar
    React.createElement(BottomNav, null)
  );
}

export default MobileApp;
